static IntList removeAll(IntList L, int x) {
    while (L != null && L.first == x) L = L.rest;  // skip matching head(s)
    if (L == null) return null;
    IntList p = L;                                // p.first != x always
    while (p.rest != null) {
        if (p.rest.first == x) p.rest = p.rest.rest;  // unlink, do NOT advance
        else p = p.rest;
    }
    return L;
}

static IntList squash(IntList L) {
    if (L == null || L.rest == null) return L;
    if (L.first == L.rest.first) {
        L.first *= 2;                  // keep L, drop its neighbour
        L.rest = squash(L.rest.rest);  // merged node is not revisited
        return L;
    }
    L.rest = squash(L.rest);
    return L;
}

static IntList[] split(IntList L) {
    if (L == null) return new IntList[]{null, null};
    IntList[] r = split(L.rest);   // r[0] = even positions of rest
    L.rest = r[1];                  // = odd positions of L after L itself
    return new IntList[]{L, r[0]};
}

static IntList rotateRight(IntList L, int k) {
    if (L == null) return null;
    int n = 1; IntList last = L;
    while (last.rest != null) { last = last.rest; n++; }
    k %= n;
    if (k == 0) return L;
    IntList p = L;
    for (int i = 0; i < n - k - 1; i++) p = p.rest;  // new tail
    IntList newHead = p.rest;
    p.rest = null;
    last.rest = L;
    return newHead;
}

